-- Crear tabla Empleados
CREATE TABLE Empleados (
    employee_id VARCHAR(8) PRIMARY KEY,
    branch_id VARCHAR(8),
    nombre VARCHAR(100),
    rol VARCHAR(20),
    horario VARCHAR(50),
    salario_base DECIMAL(8,2),
    horas_extras INT,
    status VARCHAR(20),
    vacaciones_restantes INT,
    fecha_ingreso DATE,
    fecha_egreso DATE
);

